'use strict';
// Draft generated by FreeLLMAPI (gpt-oss-20b via ovh); saved by Claude.
const { z } = require('zod');

const uuid = z.string().uuid();

const userIdParams = z.object({
  userId: uuid,
});

const requesterParams = z.object({
  requesterId: uuid,
});

const followerParams = z.object({
  followerId: uuid,
});

const respondBody = z.object({
  action: z.enum(['accept', 'reject']),
});

const pageQuery = z.object({
  limit: z.coerce
    .number()
    .int()
    .min(1)
    .max(50)
    .default(20),
  cursor: z
    .string()
    .refine((v) => !isNaN(Date.parse(v)), {
      message: 'Invalid ISO datetime',
    })
    .optional(),
});

const usernameParams = z.object({
  username: z
    .string()
    .transform((v) => v.toLowerCase())
    .refine((v) => /^[a-z0-9_.]{3,30}$/.test(v), {
      message: 'Invalid username format',
    }),
});

module.exports = {
  uuid,
  userIdParams,
  requesterParams,
  followerParams,
  respondBody,
  pageQuery,
  usernameParams,
};
